SELECT product_id, unit_price_bucket, max_quantity, avg_quantity FROM (SELECT product_id, CASE WHEN unit_price >= 350 THEN 'high' WHEN unit_price >= 60 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MAX(quantity) AS max_quantity, AVG(quantity) AS avg_quantity FROM order_items GROUP BY product_id, CASE WHEN unit_price >= 350 THEN 'high' WHEN unit_price >= 60 THEN 'mid' ELSE 'low' END) AS sub WHERE max_quantity >= 7.0 ORDER BY 3 DESC, product_id DESC;
